import React, { useMemo, useState, useEffect } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity as ActivityIcon, ArrowDown, ArrowDownToLine, ArrowRight, ArrowUp, ArrowUpRight, Backpack, CalendarDays, Check, ChevronDown, ChevronRight, CircleDollarSign, Clock3, Compass, Copy, Download, Edit3, ExternalLink, GripVertical, Heart, Leaf, MapPin, MoreHorizontal, Plus, Printer, Search, ShieldCheck, Sparkles, Trash2, TrendingUp, Wallet, X } from 'lucide-react'
import { Button, Chip, DestinationCard, EmptyState, LoadingCards, Modal, PageTitle, SectionHeading, StatCard, TravelMap } from './components.jsx'
import { starterDestinations } from './data.js'
import { api } from './services/api.js'

const date = value => value ? new Date(value) : null
const shortDate = value => date(value)?.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) || 'Date to be decided'
const dayDate = value => date(value)?.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' }) || 'A day on the road'
const currency = (value, unit = 'USD', compact = false) => { const code = /^[A-Z]{3}$/.test(unit || '') ? unit : 'USD'; return `${code} ${new Intl.NumberFormat(undefined, { style: 'currency', currency: code, maximumFractionDigits: compact ? 0 : 2, notation: compact ? 'compact' : 'standard' }).format(Number(value) || 0)}` }
const tripIdOf = expense => typeof expense.trip === 'object' ? expense.trip?._id : expense.trip
const tripName = (expense, trips) => expense.trip?.name || expense.tripName || trips.find(x => x._id === tripIdOf(expense))?.name || 'Personal expense'
const daysBetween = (start, end) => start && end ? Math.max(1, Math.ceil((new Date(end) - new Date(start)) / 86400000) + 1) : 0
const categories = ['All', 'Beaches', 'Mountains', 'Culture', 'Adventure', 'City breaks', 'Relaxation', 'Food']
const PIE_COLORS = ['#2d8175', '#e89a58', '#798bb1', '#d97762', '#a8bc8c', '#687572', '#d4b766']
const safeExpenseTotal = expenses => expenses.reduce((acc, e) => { const unit = e.currency || 'USD'; acc[unit] = (acc[unit] || 0) + Number(e.amount || 0); return acc }, {})
const sameCurrencySpent = (expenses, trip) => expenses.filter(e => tripIdOf(e) === trip._id && (e.currency || 'USD') === (trip.currency || 'USD')).reduce((sum, e) => sum + Number(e.amount || 0), 0)

export function Dashboard({ user, workspace, loading, goTo, onTripSave, onExpenseSave }) {
  const trips = workspace?.trips || [], expenses = workspace?.expenses || [], activities = workspace?.activities || []
  const destinations = workspace?.destinations || starterDestinations
  const upcoming = [...trips].filter(t => new Date(t.endDate) >= new Date()).sort((a, b) => new Date(a.startDate) - new Date(b.startDate))
  const visited = new Set(trips.filter(t => new Date(t.endDate) < new Date()).map(t => t.destinationName)).size
  const totals = safeExpenseTotal(expenses); const totalText = Object.keys(totals).length ? Object.entries(totals).map(([unit, amount]) => currency(amount, unit, true)).join(' · ') : currency(0)
  const upcomingTrip = upcoming[0]
  const tripSpend = upcomingTrip ? sameCurrencySpent(expenses, upcomingTrip) : 0
  const remaining = upcomingTrip ? Math.max(0, Number(upcomingTrip.budget) - tripSpend) : null
  const useCurrency = upcomingTrip?.currency || 'USD'
  const monthData = useMemo(() => {
    const base = new Date(); base.setDate(1)
    return Array.from({ length: 6 }, (_, i) => {
      const m = new Date(base); m.setMonth(m.getMonth() - (5 - i))
      const label = m.toLocaleDateString(undefined, { month: 'short' })
      const value = expenses.filter(x => { const d = new Date(x.date); return d.getMonth() === m.getMonth() && d.getFullYear() === m.getFullYear() && (x.currency || 'USD') === useCurrency }).reduce((s, x) => s + Number(x.amount || 0), 0)
      return { month: label, amount: value }
    })
  }, [expenses, useCurrency])
  const upcomingActivities = activities.filter(a => new Date(a.date) >= new Date() && (!upcomingTrip || (typeof a.trip === 'object' ? a.trip?._id : a.trip) === upcomingTrip._id)).sort((a, b) => new Date(a.date) - new Date(b.date)).slice(0, 3)
  if (loading && !workspace) return <div className="loading-page"><div className="loading-orbit" /><p>Gathering your travel notes…</p></div>
  return <div className="page-stack dashboard-view">
    <div className="dashboard-welcome"><div><span className="eyebrow">{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' }).toUpperCase()} · YOUR TRAVEL DESK</span><h1>Good morning, {user.name?.split(' ')[0] || 'traveler'}<span className="welcome-period">.</span></h1><p>There’s a whole world out there. Let’s make room for it.</p></div><div className="dashboard-actions"><Button variant="outline" icon={Wallet} onClick={() => goTo('/app/expenses')}>Add an expense</Button><Button icon={Plus} onClick={() => goTo('/app/trips')}>Plan a trip</Button></div></div>
    <div className="stat-grid"><StatCard label="Planned journeys" value={trips.length} note="your travel stories" icon={PlaneIcon} color="sage" /><StatCard label="Places discovered" value={visited} note="completed journeys" icon={MapPin} color="amber" /><StatCard label="Travel spending" value={totalText} note="saved expense records" icon={Wallet} color="blue" /><StatCard label="Trip budget left" value={remaining == null ? '—' : currency(remaining, useCurrency, true)} note={upcomingTrip ? `${upcomingTrip.name} · ${Math.min(100, Math.round(tripSpend / Math.max(1, Number(upcomingTrip.budget)) * 100))}% used` : 'plan a trip to set a budget'} icon={CircleDollarSign} color="rose" />
    </div>
    <div className="dashboard-main-grid"><section className="panel next-trip-panel"><div className="panel-heading"><div><span className="eyebrow">THE NEXT BIG THING</span><h2>On the horizon</h2></div><button className="quiet-icon" onClick={() => goTo('/app/trips')} aria-label="View all trips"><ArrowUpRight size={17} /></button></div>
      {upcomingTrip ? <div className="next-trip-card"><div className="next-trip-image"><img src={upcomingTrip.imageUrl || destinations.find(d => d.name === upcomingTrip.destinationName)?.imageUrl} alt={upcomingTrip.destinationName} /><div className="next-trip-shade" /><Chip tone="light">UP NEXT</Chip><div className="next-trip-place"><span>{upcomingTrip.country || 'Destination'}</span><h3>{upcomingTrip.destinationName}</h3></div></div><div className="next-trip-info"><div className="trip-date-line"><CalendarDays size={15} /><b>{shortDate(upcomingTrip.startDate)} — {shortDate(upcomingTrip.endDate)}</b><span>{daysBetween(upcomingTrip.startDate, upcomingTrip.endDate)} days</span></div><p>{upcomingTrip.description || 'A little space away, made your own.'}</p><div className="budget-track-label"><span>TRIP BUDGET</span><b>{currency(tripSpend, useCurrency)} <small>of {currency(upcomingTrip.budget, useCurrency)}</small></b></div><div className="budget-track"><span style={{ width: `${Math.min(100, Math.round(tripSpend / Math.max(1, Number(upcomingTrip.budget)) * 100))}%` }} /></div><div className="budget-assistant"><Sparkles size={12} /><span>Daily guide</span><b>{currency(Number(upcomingTrip.budget || 0) / Math.max(1, daysBetween(upcomingTrip.startDate, upcomingTrip.endDate)), useCurrency)} <small>/ day</small></b></div><div className="next-trip-links"><button onClick={() => goTo('/app/itinerary')}>Shape your itinerary <ArrowRight size={14} /></button><button onClick={() => goTo('/app/map')}>Open map <MapPin size={14} /></button></div></div></div> : <EmptyState icon={Compass} title="A trip is calling" body="Start with a place and make the rest yours." action="Plan a trip" onAction={() => goTo('/app/trips')} />}
    </section><section className="panel spending-panel"><div className="panel-heading"><div><span className="eyebrow">A LITTLE MORE CLARITY</span><h2>Travel spend</h2></div><button className="quiet-icon" onClick={() => goTo('/app/expenses')} aria-label="View expenses"><ArrowUpRight size={17} /></button></div><div className="chart-total"><strong>{currency(totals[useCurrency] || 0, useCurrency)}</strong><span>in {useCurrency} · saved expenses</span></div><div className="area-chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={monthData} margin={{ top: 10, right: 0, left: -20, bottom: 0 }}><defs><linearGradient id="spendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4e9887" stopOpacity={.25} /><stop offset="95%" stopColor="#4e9887" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="#edf0eb" vertical={false} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: '#8b9992' }} dy={8} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#9aa59e' }} tickFormatter={v => `${useCurrency} ${v}`} /><Tooltip formatter={v => currency(v, useCurrency)} contentStyle={{ border: '1px solid #e9ede8', borderRadius: 10, fontSize: 12 }} /><Area type="monotone" dataKey="amount" stroke="#418978" strokeWidth={2.4} fill="url(#spendFill)" activeDot={{ r: 4, fill: '#286f62', stroke: '#fff', strokeWidth: 2 }} /></AreaChart></ResponsiveContainer></div><div className="chart-foot"><span><span className="chart-legend-dot" />Monthly spend · {useCurrency} only</span><button onClick={() => goTo('/app/expenses')}>Explore spending <ChevronRight size={14} /></button></div></section></div>
    <div className="dashboard-lower-grid"><section className="panel activity-panel"><div className="panel-heading"><div><span className="eyebrow">THE LITTLE DETAILS</span><h2>Coming up</h2></div><button className="text-link" onClick={() => goTo('/app/itinerary')}>Full itinerary <ChevronRight size={14} /></button></div>{upcomingActivities.length ? <div className="activity-list">{upcomingActivities.map(a => <div className="activity-row" key={a._id}><div className="activity-date"><b>{date(a.date)?.toLocaleDateString(undefined, { day: '2-digit' })}</b><small>{date(a.date)?.toLocaleDateString(undefined, { month: 'short' })}</small></div><div className="activity-marker" /><div className="activity-copy"><b>{a.name}</b><span>{a.startTime || 'Time to be decided'}{a.location && ` · ${a.location}`}</span></div><span className="activity-category">{a.category}</span></div>)}</div> : <div className="inline-empty"><CalendarDays size={18} /><span>No activities coming up yet.</span><button onClick={() => goTo('/app/itinerary')}>Add one</button></div>}</section><section className="panel recent-panel"><div className="panel-heading"><div><span className="eyebrow">THE RECEIPTS, REFINED</span><h2>Recent expenses</h2></div><button className="text-link" onClick={() => goTo('/app/expenses')}>All expenses <ChevronRight size={14} /></button></div>{expenses.slice(0, 4).map(e => <div className="recent-expense" key={e._id}><span className={`expense-category-icon icon-${e.category?.toLowerCase().replaceAll(' ', '-')}`}><Wallet size={15} /></span><span className="recent-expense-title"><b>{e.title}</b><small>{shortDate(e.date)} · {tripName(e, trips)}</small></span><strong>{currency(e.amount, e.currency)}</strong></div>)}{!expenses.length && <div className="inline-empty"><Wallet size={18} /><span>Your saved expense records will appear here.</span></div>}</section></div>
    <section className="dashboard-discover"><div className="panel-heading"><div><span className="eyebrow">WHEN YOU’RE READY TO WANDER</span><h2>Somewhere worth dreaming about</h2></div><button className="text-link" onClick={() => goTo('/app/destinations')}>Explore all <ChevronRight size={14} /></button></div><div className="mini-destination-grid">{destinations.slice(0, 3).map(d => <button className="mini-destination" key={d._id} onClick={() => goTo('/app/destinations')}><img src={d.imageUrl} alt="" /><span><b>{d.name}</b><small>{d.country} · est. {currency(d.dailyCost, 'USD')} / day</small></span><ArrowUpRight size={16} /></button>)}</div></section>
  </div>
}
function PlaneIcon(props) { return <Compass {...props} /> }

export function Destinations({ workspace, loading, onFavorite, onPlan }) {
  const all = workspace?.destinations || []
  const [params] = useSearchParams()
  const [search, setSearch] = useState(params.get('search') || ''); const [category, setCategory] = useState('All'); const [sort, setSort] = useState('recommended')
  const [details, setDetails] = useState(null)
  const searchIntent = { start: params.get('start') || '', travelers: Number(params.get('travelers')) || 2, budget: params.get('budget') || '' }
  const favorites = workspace?.favorites || []
  const items = useMemo(() => {
    let data = all.filter(x => {
      const estimated = Number(x.dailyCost || 0) * Number(x.durationDays || 5) * searchIntent.travelers
      const withinBudget = !searchIntent.budget || (searchIntent.budget === '1000' && estimated <= 1000) || (searchIntent.budget === '3000' && estimated >= 1000 && estimated <= 3000) || (searchIntent.budget === '6000' && estimated >= 3000)
      return (!search || `${x.name} ${x.country} ${x.description}`.toLowerCase().includes(search.toLowerCase())) && (category === 'All' || x.categories?.includes(category)) && withinBudget
    })
    if (sort === 'price-low') data = [...data].sort((a, b) => a.dailyCost - b.dailyCost)
    if (sort === 'price-high') data = [...data].sort((a, b) => b.dailyCost - a.dailyCost)
    return data
  }, [all, search, category, sort, searchIntent.budget, searchIntent.travelers])
  return <div className="page-stack"><PageTitle eyebrow="GO WHERE YOU FEEL MOST ALIVE" title="Find your somewhere." description="A little inspiration for the places calling your name." actions={<span className="estimate-note"><Sparkles size={14} /> Cost estimates shown in USD</span>} /><div className="explorer-toolbar"><div className="search-field"><Search size={16} /><input placeholder="Search places or countries…" value={search} onChange={e => setSearch(e.target.value)} /><kbd>⌘ K</kbd></div><label className="select-filter"><span>Sort by</span><select value={sort} onChange={e => setSort(e.target.value)}><option value="recommended">Recommended</option><option value="price-low">Cost: low to high</option><option value="price-high">Cost: high to low</option></select><ChevronDown size={14} /></label></div><div className="category-pills">{categories.map(c => <button key={c} className={category === c ? 'selected' : ''} onClick={() => setCategory(c)}>{c}</button>)}</div>{loading && !all.length ? <LoadingCards /> : items.length ? <div className="destination-grid">{items.map(d => <DestinationCard key={d._id} destination={d} favorite={favorites.includes(d._id)} onFavorite={onFavorite} onPlan={item => onPlan(item, searchIntent)} onDetails={setDetails} />)}</div> : <EmptyState icon={Search} title="No places found" body="Try another name or clear your filters." action="Clear filters" onAction={() => { setSearch(''); setCategory('All') }} />}<p className="catalog-footnote">Destination descriptions and daily costs are sample planning estimates in USD. They are not live travel, weather, or availability data.</p>{details && <DestinationDetailsModal destination={details} onClose={() => setDetails(null)} onPlan={() => { onPlan(details, searchIntent); setDetails(null) }} />}</div>
}

function DestinationDetailsModal({ destination, onClose, onPlan }) {
  return <Modal title={`${destination.name}, ${destination.country}`} subtitle="Destination details · planning information" onClose={onClose} wide><div className="destination-detail-modal"><img className="detail-hero-image" src={destination.imageUrl} alt={`${destination.name}, ${destination.country}`} /><p className="detail-description">{destination.description}</p><div className="detail-stats"><div><span>DAILY COST · EST.</span><b>{currency(destination.dailyCost, 'USD')}</b></div><div><span>RECOMMENDED STAY</span><b>{destination.durationDays} days</b></div><div><span>BEST TIME · SAMPLE</span><b>{destination.bestTime || 'Not specified'}</b></div></div><div className="detail-categories">{destination.categories?.map(c => <Chip key={c}>{c}</Chip>)}</div><div className="detail-map-row"><TravelMap points={destination.coordinates ? [destination] : []} className="detail-map" /><div><span className="eyebrow">GET A FEEL FOR THE PLACE</span><h3>{destination.name}</h3><p>{destination.coordinates ? 'Approximate destination coordinates from the sample catalog.' : 'No coordinates are listed for this destination yet.'}</p>{destination.coordinates && <a className="text-link" target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/directions?to=${destination.coordinates.lat}%2C${destination.coordinates.lng}`}>Open map directions <ExternalLink size={14} /></a>}</div></div><div className="form-actions"><button type="button" className="button button-quiet" onClick={onClose}>Close</button><Button onClick={onPlan} icon={ArrowRight}>Plan a trip here</Button></div><p className="footnote">Estimated daily costs and seasonal recommendations are sample planning data, not live prices or travel advice.</p></div></Modal>
}

export function Trips({ workspace, onCreate, onEdit, onDelete, onDuplicate, onShare }) {
  const trips = workspace?.trips || []
  const upcoming = trips.filter(t => new Date(t.endDate) >= new Date()).sort((a, b) => new Date(a.startDate) - new Date(b.startDate))
  const past = trips.filter(t => new Date(t.endDate) < new Date()).sort((a, b) => new Date(b.startDate) - new Date(a.startDate))
  const TripCards = ({ list, label }) => <><SectionHeading title={label} />{list.length ? <div className="trip-grid">{list.map(t => <TripCard key={t._id} trip={t} workspace={workspace} onEdit={onEdit} onDelete={onDelete} onDuplicate={onDuplicate} onShare={onShare} />)}</div> : <div className="trip-empty">Nothing on the calendar just yet.</div>}</>
  return <div className="page-stack"><PageTitle eyebrow="YOUR JOURNEYS, AT YOUR PACE" title="My trips" description="The plans, the possibilities, and the places you’ve been." actions={<Button icon={Plus} onClick={onCreate}>Create a trip</Button>} />{!trips.length ? <EmptyState icon={Compass} title="Your travel stories start here" body="Create a trip and gather all the little details in one place." action="Plan a trip" onAction={onCreate} /> : <><section className="trip-section"><TripCards list={upcoming} label="On the horizon" /></section>{past.length > 0 && <section className="trip-section past-trip-section"><TripCards list={past} label="Journeys behind you" /></section>}</>}</div>
}
function TripCard({ trip, workspace, onEdit, onDelete, onDuplicate, onShare }) {
  const spent = sameCurrencySpent(workspace?.expenses || [], trip), percentage = trip.budget ? Math.min(100, Math.round(spent / trip.budget * 100)) : 0
  const [menu, setMenu] = useState(false)
  return <article className="trip-card"><div className="trip-card-image"><img src={trip.imageUrl || workspace?.destinations?.find(d => d.name === trip.destinationName)?.imageUrl} alt={trip.destinationName} /><span className="trip-status">{new Date(trip.endDate) < new Date() ? 'COMPLETED' : 'UPCOMING'}</span><button className="trip-menu-button" onClick={() => setMenu(!menu)} aria-label="Trip actions"><MoreHorizontal size={19} /></button>{menu && <div className="trip-menu"><button onClick={() => { onEdit(trip._id); setMenu(false) }}><Edit3 size={14} /> Edit details</button><button onClick={() => { onDuplicate(trip._id); setMenu(false) }}><Copy size={14} /> Duplicate plan</button><button onClick={() => { onShare(trip._id); setMenu(false) }}><ExternalLink size={14} /> Share read-only</button><button className="danger-text" onClick={() => { onDelete(trip._id); setMenu(false) }}><Trash2 size={14} /> Delete trip</button></div>}</div><div className="trip-card-body"><span className="trip-card-country"><MapPin size={13} /> {trip.country || 'A place to wander'}</span><h3>{trip.name}</h3><div className="trip-card-date"><CalendarDays size={14} /> {shortDate(trip.startDate)} — {shortDate(trip.endDate)}<span>· {daysBetween(trip.startDate, trip.endDate)} days</span></div><div className="trip-card-budget"><div><span>TRIP SPEND</span><b>{currency(spent, trip.currency)} <small>/ {currency(trip.budget, trip.currency)}</small></b></div><div className="budget-track"><span style={{ width: `${percentage}%` }} /></div></div><div className="trip-card-actions"><button onClick={() => onEdit(trip._id)}>Edit trip <ArrowUpRight size={14} /></button><span>{trip.travelers} {trip.travelers === 1 ? 'traveler' : 'travelers'}</span></div></div></article>
}

export function Itinerary({ workspace, onAdd, onUpdate, onDelete, onReorder }) {
  const trips = workspace?.trips || []; const [tripId, setTripId] = useState(trips[0]?._id || ''); const [modal, setModal] = useState(null); const [dragged, setDragged] = useState(null)
  useEffect(() => { if (!trips.find(x => x._id === tripId)) setTripId(trips[0]?._id || '') }, [trips, tripId])
  const trip = trips.find(x => x._id === tripId); const activities = [...(workspace?.activities || [])].filter(a => (typeof a.trip === 'object' ? a.trip?._id : a.trip) === tripId).sort((a, b) => `${a.date}`.localeCompare(`${b.date}`) || (Number(a.order || 0) - Number(b.order || 0)) || `${a.startTime || ''}`.localeCompare(`${b.startTime || ''}`))
  const days = trip ? Array.from({ length: daysBetween(trip.startDate, trip.endDate) }, (_, i) => { const d = new Date(trip.startDate); d.setDate(d.getDate() + i); return d.toISOString().slice(0, 10) }) : []
  const total = activities.filter(a => (a.currency || trip?.currency) === (trip?.currency || 'USD')).reduce((s, a) => s + Number(a.estimatedCost || 0), 0)
  const reorderDay = (day, fromId, toId) => {
    const items = activities.filter(a => new Date(a.date).toISOString().slice(0, 10) === day)
    const from = items.findIndex(a => a._id === fromId), to = items.findIndex(a => a._id === toId)
    if (from < 0 || to < 0 || from === to) return
    const [item] = items.splice(from, 1); items.splice(to, 0, item)
    onReorder(tripId, items.map(a => a._id))
  }
  const shiftDay = (day, itemId, offset) => {
    const items = activities.filter(a => new Date(a.date).toISOString().slice(0, 10) === day)
    const index = items.findIndex(a => a._id === itemId), target = index + offset
    if (target >= 0 && target < items.length) reorderDay(day, itemId, items[target]._id)
  }
  return <div className="page-stack"><PageTitle eyebrow="MAKE EVERY DAY YOURS" title="The itinerary" description="Shape each day around the things you’re looking forward to." actions={trip && <><Button variant="outline" icon={Printer} onClick={() => window.print()}>Print itinerary</Button><Button icon={Plus} onClick={() => setModal({})}>Add activity</Button></>} />
    {!trips.length ? <EmptyState icon={CalendarDays} title="Your days are still open" body="Create a trip first, then start adding the little things you want to do." action="Go to trips" onAction={() => { window.location.href = '/app/trips' }} /> : <><div className="itinerary-summary"><label><span>CHOOSE A JOURNEY</span><select value={tripId} onChange={e => setTripId(e.target.value)}>{trips.map(t => <option key={t._id} value={t._id}>{t.name}</option>)}</select><ChevronDown size={15} /></label><div className="itinerary-total"><span>ESTIMATED ACTIVITY COST</span><b>{currency(total, trip?.currency || 'USD')}</b></div><div className="itinerary-trip-dates"><CalendarDays size={15} /> {shortDate(trip?.startDate)} — {shortDate(trip?.endDate)}</div></div>{trip && <div className="itinerary-destination-banner"><img src={trip.imageUrl || workspace?.destinations?.find(d => d.name === trip.destinationName)?.imageUrl} alt="" /><div><span>{trip.country}</span><b>{trip.destinationName}</b><small>{days.length} days · {trip.travelers} travelers</small></div><p>{trip.description || 'Leave a little room for the unexpected.'}</p></div>}{days.map((day, index) => { const items = activities.filter(a => new Date(a.date).toISOString().slice(0, 10) === day); const dayCost = items.reduce((s, a) => s + Number(a.estimatedCost || 0), 0); return <section key={day} className="itinerary-day"><div className="day-heading"><div><span>DAY {String(index + 1).padStart(2, '0')}</span><h2>{dayDate(day)}</h2></div><div><small>{items.length} {items.length === 1 ? 'activity' : 'activities'}</small><b>{currency(dayCost, trip?.currency || 'USD')}</b></div></div>{items.length ? <div className="schedule-list">{items.map((a, itemIndex) => <div className={`schedule-item ${dragged === a._id ? 'schedule-dragging' : ''}`} key={a._id} draggable onDragStart={e => { setDragged(a._id); e.dataTransfer.effectAllowed = 'move' }} onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); reorderDay(day, dragged, a._id); setDragged(null) }} onDragEnd={() => setDragged(null)}><button className="drag-handle" aria-label="Drag to reorder activity"><GripVertical size={16} /></button><div className="schedule-time"><b>{a.startTime || 'Anytime'}</b><span>{a.endTime || ''}</span></div><span className={`schedule-symbol cat-${a.category}`}><ActivityIcon size={16} /></span><div className="schedule-copy"><h3>{a.name}</h3><p>{a.description || a.location || 'A little space to explore.'}</p><div>{a.location && <span><MapPin size={12} /> {a.location}</span>}<Chip>{a.category}</Chip></div></div><strong className="schedule-cost">{currency(a.estimatedCost, a.currency || trip?.currency || 'USD')}</strong><div className="schedule-actions"><button aria-label={`Move ${a.name} earlier`} onClick={() => shiftDay(day, a._id, -1)} disabled={itemIndex === 0}><ArrowUp size={13} /></button><button aria-label={`Move ${a.name} later`} onClick={() => shiftDay(day, a._id, 1)} disabled={itemIndex === items.length - 1}><ArrowDown size={13} /></button><button aria-label="Edit activity" onClick={() => setModal(a)}><Edit3 size={14} /></button><button aria-label="Delete activity" onClick={() => onDelete(a._id)}><Trash2 size={14} /></button></div></div>)}</div> : <button className="add-to-day" onClick={() => setModal({ date: day })}><Plus size={15} /> Add a little something</button>}</section>})}{activities.length === 0 && <p className="footnote">Your itinerary is yours to shape. Activity costs are estimates in {trip?.currency || 'USD'}.</p>}</>}
    {modal && trip && <ActivityModal trip={trip} initial={modal._id ? modal : undefined} defaultDate={modal.date || trip.startDate?.slice(0, 10)} activities={activities} onClose={() => setModal(null)} onSubmit={async p => { const activityId = modal._id; const result = activityId ? await onUpdate(activityId, p) : await onAdd({ trip: trip._id, data: p }); if (result !== undefined) setModal(null) }} />}
  </div>
}
function ActivityModal({ trip, initial, defaultDate, activities, onClose, onSubmit }) {
  const [form, setForm] = useState({ name: initial?.name || '', description: initial?.description || '', date: initial?.date?.slice(0, 10) || defaultDate, startTime: initial?.startTime || '09:00', endTime: initial?.endTime || '10:00', location: initial?.location || '', estimatedCost: initial?.estimatedCost || 0, currency: initial?.currency || trip.currency || 'USD', category: initial?.category || 'sightseeing', notes: initial?.notes || '', bookingReference: initial?.bookingReference || '', latitude: initial?.coordinates?.lat ?? '', longitude: initial?.coordinates?.lng ?? '' })
  const [busy, setBusy] = useState(false); const [overlap, setOverlap] = useState(false)
  const submit = async e => { e.preventDefault(); const overlapping = activities.some(a => a._id !== initial?._id && a.date?.slice(0, 10) === form.date && a.startTime && a.endTime && form.startTime < a.endTime && form.endTime > a.startTime); setOverlap(overlapping); if (overlapping) return; setBusy(true); await onSubmit({ ...form, estimatedCost: Number(form.estimatedCost), coordinates: form.latitude !== '' && form.longitude !== '' ? { lat: Number(form.latitude), lng: Number(form.longitude) } : undefined }); setBusy(false) }
  return <Modal title={initial ? 'Adjust the plan' : 'Add to your day'} subtitle={`Make room in ${trip.destinationName} for something memorable.`} onClose={onClose}><form className="modal-form" onSubmit={submit}><label>Activity name<input autoFocus required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="An early stroll through the gardens" /></label><label>What are you thinking? <small className="optional">optional</small><textarea rows="2" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="A note for future you" /></label><div className="form-row"><label>Date<input type="date" required min={trip.startDate?.slice(0, 10)} max={trip.endDate?.slice(0, 10)} value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></label><label>Category<select value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>{['sightseeing', 'food', 'transport', 'adventure', 'shopping', 'relaxation'].map(x => <option key={x}>{x}</option>)}</select></label></div><div className="form-row"><label>Starts at<input type="time" value={form.startTime} onChange={e => setForm({ ...form, startTime: e.target.value })} /></label><label>Finishes at<input type="time" value={form.endTime} onChange={e => setForm({ ...form, endTime: e.target.value })} /></label></div><div className="form-row"><label>Location<input value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} placeholder="Place or neighborhood" /></label><label>Estimated cost ({form.currency})<input type="number" min="0" step=".01" value={form.estimatedCost} onChange={e => setForm({ ...form, estimatedCost: e.target.value })} /></label></div><div className="form-row"><label>Notes <small className="optional">optional</small><textarea rows="2" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Anything to remember" /></label><label>Booking reference <small className="optional">optional</small><input value={form.bookingReference} onChange={e => setForm({ ...form, bookingReference: e.target.value })} placeholder="Confirmation code" /></label></div><div className="form-row"><label>Latitude <small className="optional">optional</small><input type="number" step="any" value={form.latitude} onChange={e => setForm({ ...form, latitude: e.target.value })} placeholder="e.g. 35.0116" /></label><label>Longitude <small className="optional">optional</small><input type="number" step="any" value={form.longitude} onChange={e => setForm({ ...form, longitude: e.target.value })} placeholder="e.g. 135.7681" /></label></div>{overlap && <div className="form-error">This time overlaps another activity on the same day. Adjust the times to continue.</div>}<div className="form-actions"><button className="button button-quiet" type="button" onClick={onClose}>Cancel</button><Button type="submit" disabled={busy} icon={Check}>{busy ? 'Saving…' : initial ? 'Save activity' : 'Add activity'}</Button></div></form></Modal>
}

export function MapPage({ workspace }) {
  const trips = workspace?.trips || []; const [tripId, setTripId] = useState(trips[0]?._id || '')
  useEffect(() => { if (!trips.find(x => x._id === tripId)) setTripId(trips[0]?._id || '') }, [trips, tripId])
  const trip = trips.find(t => t._id === tripId); const dest = workspace?.destinations?.find(d => d.name === trip?.destinationName)
  const activities = (workspace?.activities || []).filter(a => (typeof a.trip === 'object' ? a.trip?._id : a.trip) === tripId)
  const points = [...(dest?.coordinates ? [{ ...dest, name: dest.name, country: dest.country }] : []), ...activities]
  return <div className="page-stack"><PageTitle eyebrow="SEE THE JOURNEY TAKE SHAPE" title="A map of your maybe." description="Your places and planned stops, in one view." actions={trips.length > 0 && <label className="select-filter map-trip-select"><span>TRIP</span><select value={tripId} onChange={e => setTripId(e.target.value)}>{trips.map(t => <option key={t._id} value={t._id}>{t.name}</option>)}</select><ChevronDown size={14} /></label>} />{trips.length ? <><div className="map-trip-summary"><div><span className="eyebrow">YOUR ROUTE, AT A GLANCE</span><h2>{trip?.destinationName} <span>·</span> {trip?.country}</h2><p>{points.length} mapped {points.length === 1 ? 'place' : 'places'} · Coordinates shown where available</p></div><a className="button button-outline" target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/search?query=${encodeURIComponent(trip?.destinationName || '')}`}><ExternalLink size={15} /> Open map directions</a></div><TravelMap points={points} className="main-map" /><div className="map-footnote"><MapPin size={14} /> OpenStreetMap · No live GPS tracking. Locations without coordinates are left unmapped.</div><section className="mapped-stops"><SectionHeading title="Your mapped stops" />{points.length ? points.map(p => <div className="mapped-row" key={p._id || p.name}><span><MapPin size={15} /></span><div><b>{p.name}</b><small>{p.location || p.country || 'Activity stop'}{p.date && ` · ${shortDate(p.date)}`}</small></div><a target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/directions?to=${p.coordinates.lat}%2C${p.coordinates.lng}`} aria-label={`Directions to ${p.name}`}><ExternalLink size={15} /></a></div>) : <p className="muted-text">No coordinates for this trip yet. Destination markers appear when the destination is in your catalog.</p>}</section></> : <EmptyState icon={MapPin} title="Your map is waiting" body="Add a trip and its destination will have a place here." action="Explore destinations" onAction={() => { window.location.href = '/app/destinations' }} />}</div>
}

export function Expenses({ workspace, onCreate, onDelete, onUpdate }) {
  const expenses = workspace?.expenses || [], trips = workspace?.trips || []
  const [search, setSearch] = useState(''); const [category, setCategory] = useState('All'); const [tripFilter, setTripFilter] = useState('All'); const [currencyFilter, setCurrencyFilter] = useState('All'); const [fromDate, setFromDate] = useState(''); const [toDate, setToDate] = useState(''); const [edit, setEdit] = useState(null)
  const currencyCodes = [...new Set(expenses.map(e => e.currency || 'USD'))]
  const filtered = expenses.filter(e => (!search || `${e.title} ${tripName(e, trips)}`.toLowerCase().includes(search.toLowerCase())) && (category === 'All' || e.category === category) && (tripFilter === 'All' || tripIdOf(e) === tripFilter) && (currencyFilter === 'All' || (e.currency || 'USD') === currencyFilter) && (!fromDate || new Date(e.date) >= new Date(`${fromDate}T00:00:00`)) && (!toDate || new Date(e.date) <= new Date(`${toDate}T23:59:59`))).sort((a, b) => new Date(b.date) - new Date(a.date))
  const totals = safeExpenseTotal(filtered), sumText = Object.entries(totals).map(([unit, value]) => currency(value, unit)).join(' · ') || currency(0)
  const pieData = currencyFilter === 'All' ? [] : Object.entries(filtered.reduce((acc, e) => { const k = e.category || 'Miscellaneous'; acc[k] = (acc[k] || 0) + Number(e.amount || 0); return acc }, {})).map(([name, value]) => ({ name, value }))
  const tripsBudgets = trips.map(t => ({ ...t, spent: sameCurrencySpent(expenses, t) })).filter(t => tripFilter === 'All' || t._id === tripFilter)
  const exportCsv = () => {
    const clean = value => { const s = String(value ?? '').replaceAll('"', '""'); return /^[=+\-@]/.test(s) ? `'${s}` : s }
    const rows = [['Title', 'Category', 'Amount', 'Currency', 'Date', 'Payment method', 'Trip'], ...filtered.map(e => [e.title, e.category, e.amount, e.currency || 'USD', new Date(e.date).toISOString().slice(0, 10), e.paymentMethod, tripName(e, trips)])]
    const content = rows.map(row => row.map(v => `"${clean(v)}"`).join(',')).join('\r\n')
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([content], { type: 'text/csv;charset=utf-8' })); a.download = 'voyage-expenses.csv'; a.click(); URL.revokeObjectURL(a.href)
  }
  return <div className="page-stack"><PageTitle eyebrow="EVERY LITTLE THING, ACCOUNTED FOR" title="The money side." description="Thoughtful spending, clear at a glance." actions={<><Button variant="outline" icon={Download} onClick={exportCsv}>Export CSV</Button><Button icon={Plus} onClick={onCreate}>Add expense</Button></>} />
    <div className="expense-overview-grid"><div className="expense-total-card"><span className="eyebrow">VISIBLE EXPENSES</span><strong>{sumText}</strong><p>{filtered.length} saved {filtered.length === 1 ? 'transaction' : 'transactions'} · grouped by currency</p><div className="expense-total-accent"><TrendingUp size={19} /></div></div><div className="expense-pie-card"><div><span className="eyebrow">WHERE IT GOES</span><h3>Spending by category {currencyFilter !== 'All' && <small>· {currencyFilter}</small>}</h3></div>{pieData.length ? <div className="pie-layout"><ResponsiveContainer width="48%" height={150}><PieChart><Pie data={pieData} dataKey="value" innerRadius={42} outerRadius={66} paddingAngle={3}>{pieData.map((x, i) => <Cell key={x.name} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}</Pie><Tooltip formatter={(v, n) => [currency(v, currencyFilter), n]} /></PieChart></ResponsiveContainer><div className="pie-legend">{pieData.slice(0, 5).map((x, i) => <div key={x.name}><i style={{ background: PIE_COLORS[i % PIE_COLORS.length] }} /><span>{x.name}</span><b>{currency(x.value, currencyFilter, true)}</b></div>)}</div></div> : <div className="pie-empty">{currencyFilter === 'All' && currencyCodes.length > 0 ? 'Choose one currency in the filters to compare category spending without mixing amounts.' : 'Your category breakdown will appear after you add expenses.'}</div>}</div></div>
    {tripsBudgets.length > 0 && <div className="budget-comparison-row">{tripsBudgets.slice(0, 3).map(t => { const pct = t.budget ? Math.round(t.spent / t.budget * 100) : 0; return <div className="budget-compare" key={t._id}><div><span>{t.destinationName}</span><Chip tone={pct >= 100 ? 'warn' : 'muted'}>{pct}% used</Chip></div><p>{currency(t.spent, t.currency)} <small>of {currency(t.budget, t.currency)}</small></p><div className="budget-track"><span className={pct >= 100 ? 'over-budget' : ''} style={{ width: `${Math.min(pct, 100)}%` }} /></div>{pct >= 100 && <small className="budget-alert">Trip spending is at or over budget.</small>}</div>})}</div>}
    <div className="expense-toolbar"><div className="search-field"><Search size={15} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Find an expense…" /></div><label className="compact-select"><select value={tripFilter} onChange={e => setTripFilter(e.target.value)}><option value="All">All trips</option>{trips.map(t => <option value={t._id} key={t._id}>{t.name}</option>)}</select><ChevronDown size={14} /></label><label className="compact-select"><select value={category} onChange={e => setCategory(e.target.value)}>{['All', 'Flights', 'Accommodation', 'Food', 'Transportation', 'Activities', 'Shopping', 'Miscellaneous'].map(x => <option key={x}>{x}</option>)}</select><ChevronDown size={14} /></label><label className="compact-select"><select value={currencyFilter} onChange={e => setCurrencyFilter(e.target.value)}><option value="All">All currencies</option>{currencyCodes.map(x => <option value={x} key={x}>{x}</option>)}</select><ChevronDown size={14} /></label><label className="date-filter"><span>FROM</span><input aria-label="From date" type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} /></label><label className="date-filter"><span>TO</span><input aria-label="To date" type="date" min={fromDate || undefined} value={toDate} onChange={e => setToDate(e.target.value)} /></label></div>
    <section className="panel transaction-panel"><div className="table-heading"><div><h2>Transaction history</h2><span>{filtered.length} {filtered.length === 1 ? 'record' : 'records'}</span></div><span className="estimate-note"><CircleDollarSign size={14} /> Original currencies kept</span></div>{filtered.length ? <div className="transaction-table-wrap"><table className="transaction-table"><thead><tr><th>WHAT</th><th>CATEGORY</th><th>TRIP</th><th>DATE</th><th>PAYMENT</th><th>AMOUNT</th><th></th></tr></thead><tbody>{filtered.map(e => <tr key={e._id}><td><b>{e.title}</b><small>{e.notes}</small></td><td><Chip>{e.category}</Chip></td><td>{tripName(e, trips)}</td><td>{shortDate(e.date)}</td><td>{e.paymentMethod || '—'}</td><td className="amount-cell">{currency(e.amount, e.currency)}</td><td className="table-actions"><button aria-label="Edit expense" onClick={() => setEdit(e)}><Edit3 size={14} /></button><button aria-label="Delete expense" onClick={() => onDelete(e._id)}><Trash2 size={14} /></button></td></tr>)}</tbody></table></div> : <EmptyState icon={Wallet} title="No expenses in this view" body="Add your first expense or try another filter." action="Add an expense" onAction={onCreate} />}</section>
    <p className="footnote">Totals are calculated from your saved expense records. Different currencies are shown separately; no conversion is assumed.</p>
    {edit && <ExpenseEditModal expense={edit} trips={trips} onClose={() => setEdit(null)} onSubmit={async p => { const result = await onUpdate(edit._id, p); if (result !== undefined) setEdit(null) }} />}
  </div>
}
function ExpenseEditModal({ expense, trips, onClose, onSubmit }) {
  const [form, setForm] = useState({ title: expense.title || '', amount: expense.amount, currency: expense.currency || 'USD', category: expense.category, date: expense.date?.slice(0, 10), trip: tripIdOf(expense) || '', paymentMethod: expense.paymentMethod || 'Card', notes: expense.notes || '' })
  return <Modal title="Edit expense" subtitle="Update the saved transaction." onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); onSubmit({ ...form, amount: Number(form.amount), trip: form.trip || undefined }) }}><label>Title<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><div className="form-row"><label>Amount<input required type="number" min=".01" step=".01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} /></label><label>Currency<select value={form.currency} onChange={e => setForm({ ...form, currency: e.target.value })}>{['USD', 'EUR', 'GBP', 'INR', 'JPY', 'AUD', 'CAD'].map(x => <option key={x}>{x}</option>)}</select></label></div><div className="form-row"><label>Category<select value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>{['Flights', 'Accommodation', 'Food', 'Transportation', 'Activities', 'Shopping', 'Miscellaneous'].map(x => <option key={x}>{x}</option>)}</select></label><label>Date<input required type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></label></div><div className="form-row"><label>Related trip<select value={form.trip} onChange={e => setForm({ ...form, trip: e.target.value })}><option value="">Personal expense</option>{trips.map(t => <option key={t._id} value={t._id}>{t.name}</option>)}</select></label><label>Payment method<input value={form.paymentMethod} onChange={e => setForm({ ...form, paymentMethod: e.target.value })} /></label></div><label>Notes<textarea rows="2" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></label><div className="form-actions"><button className="button button-quiet" type="button" onClick={onClose}>Cancel</button><Button type="submit" icon={Check}>Save changes</Button></div></form></Modal>
}

export function Packing({ workspace, onAdd, onUpdate, onToggle, onDelete }) {
  const trips = workspace?.trips || []; const [tripId, setTripId] = useState(trips[0]?._id || ''); const [name, setName] = useState(''); const [category, setCategory] = useState('Essentials'); const [editing, setEditing] = useState(null)
  useEffect(() => { if (!trips.find(x => x._id === tripId)) setTripId(trips[0]?._id || '') }, [trips, tripId])
  const items = (workspace?.packing || []).filter(x => x.trip === tripId); const packed = items.filter(x => x.packed).length; const pct = items.length ? Math.round(packed / items.length * 100) : 0
  return <div className="page-stack"><PageTitle eyebrow="PACK LIGHT, FEEL READY" title="The packing list." description="A little less last-minute, a little more room for the good stuff." actions={trips.length > 0 && <label className="select-filter"><span>TRIP</span><select value={tripId} onChange={e => setTripId(e.target.value)}>{trips.map(t => <option key={t._id} value={t._id}>{t.name}</option>)}</select><ChevronDown size={14} /></label>} />{trips.length ? <><div className="packing-progress"><div className="packing-progress-top"><div><span className="eyebrow">{items.length ? 'READY WHEN YOU ARE' : 'START WITH THE ESSENTIALS'}</span><h2>{packed} of {items.length} packed</h2></div><b>{pct}%</b></div><div className="packing-progress-bar"><span style={{ width: `${pct}%` }} /></div><p>For {trips.find(t => t._id === tripId)?.destinationName} · {shortDate(trips.find(t => t._id === tripId)?.startDate)}</p></div><form className="packing-add" onSubmit={e => { e.preventDefault(); if (!name.trim()) return; onAdd(tripId, { name: name.trim(), category }); setName('') }}><label><span>ADD A LITTLE SOMETHING</span><input value={name} onChange={e => setName(e.target.value)} placeholder="A book for the train ride…" /></label><select value={category} onChange={e => setCategory(e.target.value)}>{['Essentials', 'Clothing', 'Toiletries', 'Documents', 'Electronics', 'Other'].map(x => <option key={x}>{x}</option>)}</select><Button type="submit" icon={Plus}>Add item</Button></form>{items.length ? <div className="packing-list">{items.map(item => <div className={`packing-item ${item.packed ? 'packed' : ''}`} key={item._id}><button className="packing-check" aria-label={item.packed ? `Mark ${item.name} unpacked` : `Mark ${item.name} packed`} onClick={() => onToggle(item._id, !item.packed)}>{item.packed && <Check size={14} />}</button><span className="packing-item-name">{item.name}</span><Chip>{item.category || 'Other'}</Chip><button className="quiet-icon" aria-label={`Edit ${item.name}`} onClick={() => setEditing(item)}><Edit3 size={14} /></button><button className="quiet-icon" aria-label={`Remove ${item.name}`} onClick={() => onDelete(item._id)}><Trash2 size={15} /></button></div>)}</div> : <EmptyState icon={Backpack} title="An empty bag, full of potential" body="Add the things you don’t want to leave behind." />}</> : <EmptyState icon={Backpack} title="Make a trip to start packing" body="Your checklist is organized by trip, so every list stays in the right place." action="Plan a trip" onAction={() => { window.location.href = '/app/trips' }} />}{editing && <PackingEditModal item={editing} onClose={() => setEditing(null)} onSubmit={async payload => { const result = await onUpdate(editing._id, payload); if (result !== undefined) setEditing(null) }} />}</div>
}
function PackingEditModal({ item, onClose, onSubmit }) {
  const [name, setName] = useState(item.name); const [category, setCategory] = useState(item.category || 'Other')
  return <Modal title="Edit packing item" subtitle="Keep the list just right for this trip." onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); onSubmit({ name: name.trim(), category }) }}><label>Item name<input required value={name} onChange={e => setName(e.target.value)} /></label><label>Category<select value={category} onChange={e => setCategory(e.target.value)}>{['Essentials', 'Clothing', 'Toiletries', 'Documents', 'Electronics', 'Other'].map(x => <option key={x}>{x}</option>)}</select></label><div className="form-actions"><button className="button button-quiet" type="button" onClick={onClose}>Cancel</button><Button type="submit" icon={Check}>Save item</Button></div></form></Modal>
}

export function Journal({ workspace, onAdd, onUpdate, onDelete }) {
  const trips = workspace?.trips || []; const [tripId, setTripId] = useState(trips[0]?._id || ''); const [modal, setModal] = useState(null)
  useEffect(() => { if (!trips.find(x => x._id === tripId)) setTripId(trips[0]?._id || '') }, [trips, tripId])
  const entries = (workspace?.journal || []).filter(x => x.trip === tripId).sort((a, b) => new Date(b.date) - new Date(a.date))
  return <div className="page-stack"><PageTitle eyebrow="KEEP A LITTLE OF THE JOURNEY" title="A journal for the road." description="The colors, the conversations, the tiny things you’ll want to remember." actions={trips.length > 0 && <><label className="select-filter"><span>TRIP</span><select value={tripId} onChange={e => setTripId(e.target.value)}>{trips.map(t => <option key={t._id} value={t._id}>{t.name}</option>)}</select><ChevronDown size={14} /></label><Button icon={Plus} onClick={() => setModal({})}>Add a memory</Button></>} />{trips.length ? entries.length ? <div className="journal-timeline">{entries.map((entry, i) => <article className="journal-entry" key={entry._id}><div className="journal-line"><span>{i + 1}</span></div><div className="journal-card">{entry.imageUrl && <img src={entry.imageUrl} alt="" loading="lazy" />}<div className="journal-content"><div className="journal-entry-meta"><span>{shortDate(entry.date)}</span>{entry.location && <><i /> <span>{entry.location}</span></>}</div><h2>{entry.title}</h2><p>{entry.body}</p><div className="journal-actions"><button className="journal-delete" onClick={() => setModal(entry)}><Edit3 size={14} /> Edit memory</button><button className="journal-delete" onClick={() => onDelete(entry._id)}><Trash2 size={14} /> Remove entry</button></div></div></div></article>)}</div> : <EmptyState icon={Leaf} title="The first page is still blank" body="Save a moment from the trip you want to remember." action="Write a memory" onAction={() => setModal({})} /> : <EmptyState icon={Leaf} title="A trip is the start of a story" body="Create one first, then save the moments along the way." action="Plan a trip" onAction={() => { window.location.href = '/app/trips' }} />}{modal && <JournalModal tripId={tripId} initial={modal._id ? modal : null} onClose={() => setModal(null)} onSubmit={async payload => { const result = modal._id ? await onUpdate(modal._id, payload) : await onAdd(tripId, payload); if (result !== undefined) setModal(null) }} />}</div>
}
function JournalModal({ tripId, initial, onClose, onSubmit }) {
  const [form, setForm] = useState({ title: initial?.title || '', body: initial?.body || '', date: initial?.date?.slice(0, 10) || new Date().toISOString().slice(0, 10), imageUrl: initial?.imageUrl || '', location: initial?.location || '' })
  return <Modal title={initial ? 'Edit this memory' : 'Save a little memory'} subtitle="A note, a place, a moment worth keeping." onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); onSubmit({ ...form, imageUrl: form.imageUrl || undefined }) }}><label>Give the moment a name<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="The light on the water" /></label><div className="form-row"><label>When<input required type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></label><label>Where <small className="optional">optional</small><input value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} placeholder="A beach, a street…" /></label></div><label>Your note<textarea rows="4" value={form.body} onChange={e => setForm({ ...form, body: e.target.value })} placeholder="What do you want to remember?" /></label><label>Image URL <small className="optional">optional</small><input type="url" value={form.imageUrl} onChange={e => setForm({ ...form, imageUrl: e.target.value })} placeholder="https://…" /></label><div className="form-actions"><button className="button button-quiet" type="button" onClick={onClose}>Cancel</button><Button type="submit" icon={Check}>{initial ? 'Save changes' : 'Save memory'}</Button></div></form></Modal>
}

export function Wishlist({ workspace, onFavorite, onPlan }) {
  const favorites = workspace?.favorites || []; const destinations = (workspace?.destinations || starterDestinations).filter(d => favorites.includes(d._id))
  return <div className="page-stack"><PageTitle eyebrow="FOR THE PLACES YOU’RE NOT DONE DREAMING ABOUT" title="The maybe list." description="Keep the places that are starting to feel like a plan." actions={<Link className="button button-outline" to="/app/destinations"><Compass size={16} /> Find more places</Link>} />{destinations.length ? <div className="destination-grid">{destinations.map(d => <DestinationCard key={d._id} destination={d} favorite onFavorite={onFavorite} onPlan={onPlan} />)}</div> : <EmptyState icon={Heart} title="Save a place for later" body="Tap the little heart on a destination and it’ll find its way here." action="Explore destinations" onAction={() => { window.location.href = '/app/destinations' }} />}</div>
}

export function Profile({ user, onSave, onSignOut }) {
  const [name, setName] = useState(user.name || ''); const [currencyCode, setCurrencyCode] = useState(user.preferences?.currency || 'USD'); const [busy, setBusy] = useState(false)
  return <div className="page-stack"><PageTitle eyebrow="A FEW DETAILS ABOUT YOU" title="Your space." description="Keep your account and travel preferences feeling like yours." /><div className="profile-layout"><section className="panel profile-card"><span className="profile-avatar profile-avatar-large">{user.name?.split(' ').map(x => x[0]).slice(0, 2).join('')}</span><div><h2>{user.name}</h2><p>{user.email}</p><Chip tone={user.role === 'admin' ? 'green' : 'muted'}>{user.role === 'admin' ? 'Administrator' : 'Traveler'}</Chip></div><div className="profile-separator" /><form className="profile-form" onSubmit={async e => { e.preventDefault(); setBusy(true); await onSave({ name, preferences: { ...(user.preferences || {}), currency: currencyCode } }); setBusy(false) }}><label>Your name<input required minLength="2" value={name} onChange={e => setName(e.target.value)} /></label><label>Preferred currency<select value={currencyCode} onChange={e => setCurrencyCode(e.target.value)}>{['USD', 'EUR', 'GBP', 'INR', 'JPY', 'AUD', 'CAD'].map(x => <option key={x}>{x}</option>)}</select></label><Button type="submit" disabled={busy} icon={Check}>{busy ? 'Saving…' : 'Save preferences'}</Button></form></section><section className="panel security-card"><div className="feature-icon"><ShieldCheck size={20} /></div><h2>Your space, your plans.</h2><p>Your saved trips, journal notes, and expense records are associated with your account. Sample demo records stay in this browser only.</p><div className="security-details"><div><span>ACCOUNT</span><b>{user.email}</b></div><div><span>ACCESS</span><b>{user.role === 'admin' ? 'Admin permissions' : 'Personal traveler'}</b></div><div><span>MODE</span><b>{user.demo ? 'Local demo' : 'Authenticated account'}</b></div></div><button className="signout-button" onClick={onSignOut}>Sign out <ArrowRight size={15} /></button></section></div><p className="footnote">Password changes and account deletion are not available in this workspace. A MongoDB-backed account is required for persistent profile storage.</p></div>
}

export function Admin({ workspace, user, run }) {
  const [stats, setStats] = useState(null); const [error, setError] = useState(''); const [modal, setModal] = useState(false); const [refreshKey, setRefreshKey] = useState(0)
  useEffect(() => { if (user.role !== 'admin') return; api.adminOverview().then(setStats).catch(e => setError(e.message)) }, [user.role, refreshKey])
  if (user.role !== 'admin') return <div className="page-stack"><PageTitle eyebrow="PLATFORM TOOLS" title="Admin studio" description="This area is restricted to authorized administrators." /><EmptyState icon={ShieldCheck} title="Administrator access required" body="Sign in with an account that has the admin role to manage the destination catalog and review platform records." /></div>
  return <div className="page-stack"><PageTitle eyebrow="PLATFORM TOOLS" title="Admin studio" description="A protected view of platform records and destination content." actions={<Button icon={Plus} onClick={() => setModal(true)}>Add destination</Button>} /><div className="stat-grid admin-stats"><StatCard label="Traveler accounts" value={stats?.counts.users ?? '—'} note="registered accounts" icon={Compass} /><StatCard label="Catalog places" value={stats?.counts.destinations ?? '—'} note="published destinations" icon={MapPin} /><StatCard label="Saved trips" value={stats?.counts.trips ?? '—'} note="across the platform" icon={CalendarDays} /><StatCard label="Expenses" value={stats?.counts.expenses ?? '—'} note="private records" icon={Wallet} /></div>{error && <div className="form-error">{error}</div>}<section className="panel transaction-panel"><div className="table-heading"><div><h2>Recent traveler accounts</h2><span>Limited to safe account fields</span></div><ShieldCheck size={17} /></div>{stats?.latestUsers?.length ? <div className="transaction-table-wrap"><table className="transaction-table"><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>JOINED</th></tr></thead><tbody>{stats.latestUsers.map(u => <tr key={u._id}><td><b>{u.name}</b></td><td>{u.email}</td><td><Chip>{u.role}</Chip></td><td>{shortDate(u.createdAt)}</td></tr>)}</tbody></table></div> : <p className="muted-text admin-empty">{stats ? 'No accounts to display yet.' : 'Loading protected platform records…'}</p>}</section><section className="panel admin-destination-panel"><div className="table-heading"><div><h2>Destination catalog</h2><span>Public destination information and sample cost estimates</span></div></div><div className="admin-destination-list">{workspace?.destinations?.map(d => <div key={d._id}><img src={d.imageUrl} alt="" /><span><b>{d.name}</b><small>{d.country} · est. {currency(d.dailyCost, 'USD')}/day</small></span><button aria-label={`Edit ${d.name}`} onClick={() => setModal(d)}><Edit3 size={15} /></button><button aria-label={`Delete ${d.name}`} onClick={() => { if (!window.confirm(`Remove ${d.name} from the destination catalog?`)) return; run(() => api.deleteDestination(d._id), 'Destination removed.').then(() => setRefreshKey(x => x + 1)) }}><Trash2 size={15} /></button></div>)}</div></section>{modal && <DestinationAdminModal initial={typeof modal === 'object' ? modal : null} onClose={() => setModal(false)} onSubmit={payload => { const promise = modal?._id ? api.updateDestination(modal._id, payload) : api.createDestination(payload); run(() => promise, modal?._id ? 'Destination updated.' : 'Destination added.').then(result => { if (result) { setModal(false); setRefreshKey(x => x + 1) } }) }} />}</div>
}
function DestinationAdminModal({ initial, onClose, onSubmit }) {
  const [form, setForm] = useState({ name: initial?.name || '', country: initial?.country || '', imageUrl: initial?.imageUrl || '', description: initial?.description || '', dailyCost: initial?.dailyCost || 0, durationDays: initial?.durationDays || 3, bestTime: initial?.bestTime || '', categories: initial?.categories?.join(', ') || '', lat: initial?.coordinates?.lat ?? '', lng: initial?.coordinates?.lng ?? '' })
  return <Modal title={initial ? 'Edit destination' : 'Add a destination'} subtitle="Catalog content is public. Clearly label cost figures as estimates." onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); onSubmit({ name: form.name, country: form.country, imageUrl: form.imageUrl, description: form.description, dailyCost: Number(form.dailyCost), durationDays: Number(form.durationDays), bestTime: form.bestTime, categories: form.categories.split(',').map(x => x.trim()).filter(Boolean), coordinates: form.lat !== '' && form.lng !== '' ? { lat: Number(form.lat), lng: Number(form.lng) } : undefined }) }}><div className="form-row"><label>Name<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>Country<input required value={form.country} onChange={e => setForm({ ...form, country: e.target.value })} /></label></div><label>Image URL<input type="url" value={form.imageUrl} onChange={e => setForm({ ...form, imageUrl: e.target.value })} /></label><label>Description<textarea rows="2" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><div className="form-row"><label>Daily cost estimate<input required type="number" min="0" value={form.dailyCost} onChange={e => setForm({ ...form, dailyCost: e.target.value })} /></label><label>Recommended days<input required type="number" min="1" value={form.durationDays} onChange={e => setForm({ ...form, durationDays: e.target.value })} /></label></div><div className="form-row"><label>Best time to visit<input value={form.bestTime} onChange={e => setForm({ ...form, bestTime: e.target.value })} /></label><label>Categories, comma separated<input value={form.categories} onChange={e => setForm({ ...form, categories: e.target.value })} /></label></div><div className="form-row"><label>Latitude <small className="optional">optional</small><input type="number" step="any" value={form.lat} onChange={e => setForm({ ...form, lat: e.target.value })} /></label><label>Longitude <small className="optional">optional</small><input type="number" step="any" value={form.lng} onChange={e => setForm({ ...form, lng: e.target.value })} /></label></div><div className="form-actions"><button className="button button-quiet" type="button" onClick={onClose}>Cancel</button><Button type="submit" icon={Check}>{initial ? 'Save destination' : 'Add destination'}</Button></div></form></Modal>
}
